function normalizeRagText(text: string): string {
  return (text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const STOP_WORDS = new Set([
  'ola', 'oi', 'bom', 'dia', 'boa', 'tarde', 'noite', 'tudo', 'bem', 'como', 'vai',
  'quero', 'queria', 'gostaria', 'saber', 'sobre', 'voce', 'voces', 'tem', 'fazem',
  'para', 'com', 'sem', 'por', 'favor', 'obrigado', 'obrigada', 'meu', 'minha',
  'qual', 'quais', 'quanto', 'custa', 'valor', 'preco', 'cotacao', 'orcamento',
  'seguro', 'seguros', 'plano', 'planos', 'preciso', 'estou', 'aqui', 'falar',
  'pode', 'poderia', 'ajudar', 'sim', 'nao', 'mais', 'muito', 'esse', 'essa', 'isso'
]);

/**
 * Retrieves ONLY the top relevant MA Corretora product sheets on-demand (<1ms).
 * Keeps greetings and unrelated messages completely lightweight while giving Sofia
 * surgical knowledge of all 99 products, coverages, and consulting services.
 */
export function retrieveMaCorretoraContext(
  currentMessage: string,
  historyText: string = '',
  maxResults: number = 4,
  maxChars: number = 4200
): {
  contextText: string;
  matchedTitles: string[];
  topItem: MaCorretoraRagItem | null;
} {
  const normCurrent = normalizeRagText(currentMessage);
  const normHistory = normalizeRagText(historyText);

  const currentTokens = normCurrent
    .split(' ')
    .filter((w) => w.length >= 3 && !STOP_WORDS.has(w));
  const historyTokens = normHistory
    .split(' ')
    .filter((w) => w.length >= 3 && !STOP_WORDS.has(w));

  if (currentTokens.length === 0 && historyTokens.length === 0) {
    return { contextText: '', matchedTitles: [], topItem: null };
  }

  const scored: Array<{ item: MaCorretoraRagItem; score: number }> = [];

  for (const item of MA_CORRETORA_RAG_ITEMS) {
    const normTitle = normalizeRagText(item.title);
    const normCat = normalizeRagText(item.category);
    const normContent = normalizeRagText(item.content);
    let score = 0;

    const titleShort = normTitle.replace(/^seguro\s+(de\s+|para\s+)?/, '').trim();
    if (titleShort.length >= 4 && normCurrent.includes(titleShort)) {
      score += 55;
    }

    for (const kw of item.keywords) {
      const nKw = normalizeRagText(kw);
      if (!nKw || nKw.length < 3) continue;
      if (normCurrent.includes(nKw)) {
        score += nKw.includes(' ') ? 24 : 14;
      } else if (normHistory.includes(nKw)) {
        score += nKw.includes(' ') ? 8 : 4;
      }
    }

    for (const tok of currentTokens) {
      if (normTitle.includes(tok)) score += 16;
      else if (normCat.includes(tok)) score += 7;
      else if (normContent.includes(tok)) score += 4;
    }

    if (currentTokens.length <= 2) {
      for (const tok of historyTokens) {
        if (normTitle.includes(tok)) score += 5;
      }
    }

    if (score >= 12) {
      scored.push({ item, score });
    }
  }

  scored.sort((a, b) => b.score - a.score);
  const top = scored.slice(0, maxResults);

  if (top.length === 0) {
    return { contextText: '', matchedTitles: [], topItem: null };
  }

  const lines: string[] = [
    '[RAG SOB DEMANDA — FICHAS TÉCNICAS OFICIAIS MA CORRETORA (EXTRAÍDAS DO SITE OFICIAL)]',
  ];
  let totalLen = lines[0].length;
  const matchedTitles: string[] = [];

  for (const { item } of top) {
    const block = '• ' + item.title + ' [' + item.category + '] (' + item.url + ')\n  Detalhes e Coberturas: ' + item.content;
    if (totalLen + block.length + 2 > maxChars && matchedTitles.length > 0) {
      break;
    }
    lines.push(block);
    matchedTitles.push(item.title);
    totalLen += block.length + 2;
  }

  return {
    contextText: lines.join('\n\n'),
    matchedTitles,
    topItem: top[0]?.item || null,
  };
}
